const fs=require('fs'),path=require('path'),dir=b._designsDir();fs.mkdirSync(dir,{recursive:true});
const saved={...b.recipe,species:'human',weight:.8},elf=RRCharacterModel.withSpecies(b.recipe,'elf');
fs.writeFileSync(path.join(dir,'Saved preview A.json'),JSON.stringify({recipe:saved}));fs.writeFileSync(path.join(dir,'Saved preview B.json'),JSON.stringify({recipe:elf}));
const wait=async(predicate,label)=>{const until=performance.now()+45000;while(!predicate()){if(performance.now()>until)throw Error('Timed out: '+label+' '+JSON.stringify({paused:b._previewPaused,owed:b._rebuildOwed,busy:b._liveJob?.busy,settle:!!b._settle,status:b.root.querySelector('.rr-c3d-status').textContent}));await new Promise(r=>setTimeout(r,25));}};
const ready=()=>b._view&&b._result&&JSON.stringify(b.recipe)===JSON.stringify(b._result.recipe)&&!b._pending&&!b._liveJob?.busy;
window.dispatchEvent(new Event('focus'));await wait(()=>!b._previewPaused,'initial focus');
if(typeof b._previewActivityOff!=='function')throw Error('Missing activity listener after view creation');
window.dispatchEvent(new Event('blur'));await wait(()=>b._previewPaused,'pause');
const previous=b._result;b._openDesign('','Saved preview A');await new Promise(r=>setTimeout(r,100));
if(b._result!==previous||/^Opened/.test(b.root.querySelector('.rr-c3d-status').textContent))throw Error('Paused open reported completion');
window.dispatchEvent(new Event('focus'));await wait(()=>ready()&&b._result!==previous,'open after focus');
if(b.root.querySelector('.rr-c3d-status').textContent!=='Opened Saved preview A.')throw Error('Missing completed open message');
b._openDesign('','Saved preview B');await wait(()=>ready()&&b._result.recipe.species==='elf','second saved design');
const button=b.root.querySelector('[data-act=species][data-id=dwarf]');if(!button)throw Error('Missing dwarf species button');button.click();await wait(()=>ready()&&b._result.recipe.species==='dwarf','species after opening');
const host=b.root,pc=b.projectController,last=b._result;b.detach();b.renderInto(host,pc);await wait(()=>ready()&&b._result!==last,'reopen builder');
window.dispatchEvent(new Event('blur'));b._openDesign('','Saved preview A');window.dispatchEvent(new Event('focus'));await wait(()=>ready()&&b._result.recipe.species==='human','open after builder reopen');
return {focusResume:true,savedDesigns:2,speciesAfterOpen:'dwarf',reopenedBuilder:true,finalSpecies:b._result.recipe.species,status:b.root.querySelector('.rr-c3d-status').textContent};
